    public suspend fun list(agentId: String? = null, limit: Long? = null, cursor: String? = null, archived: ListSessionsArchived? = null, pinned: ListSessionsPinned? = null, options: RequestOptions = RequestOptions()): ListSessionsResponse {
        val query = buildList {
            if (agentId != null) add("agent_id" to agentId)
            if (limit != null) add("limit" to limit.toString())
            if (cursor != null) add("cursor" to cursor)
            if (archived != null) add("archived" to archived.value)
            if (pinned != null) add("pinned" to pinned.value)
        }
        return client.request<ListSessionsResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/sessions",
                query = query,
                options = options,
            )
        )
    }

    /**
     * Stream every item returned by `listSessions`, following the `cursor` cursor until the server
     * reports no further pages.
     */
    public fun listAll(agentId: String? = null, limit: Long? = null, cursor: String? = null, archived: ListSessionsArchived? = null, pinned: ListSessionsPinned? = null, options: RequestOptions = RequestOptions()): Flow<ListSessionsResponseItem> = autoPaginate(
        fetch = { pageCursor -> list(agentId = agentId, limit = limit, cursor = pageCursor, archived = archived, pinned = pinned, options = options) },
        items = { it.items },
        cursor = { it.cursor },
        hasMore = { it.hasMore },
    )

    /**
     * List session annotations
     *
     * Lists the comment annotations left on this session's messages, up to 500, each with the
     * `message_id` it is anchored to, its author and whether it has been resolved. `404` when the
     * session does not exist. Message ids are the derived, stable ids that reactions and bookmarks
     * also key on.
     *
     * `GET /api/v1/sessions/{sessionId}/annotations`
     *
     * Required scopes: `sessions:read`.
     */
    public suspend fun listSessionAnnotations(sessionId: String, limit: Long? = null, cursor: String? = null, options: RequestOptions = RequestOptions()): ListSessionAnnotationsResponse {
        val query = buildList {
            if (limit != null) add("limit" to limit.toString())
            if (cursor != null) add("cursor" to cursor)
        }
        return client.request<ListSessionAnnotationsResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/annotations",
                query = query,
                options = options,
            )
        )
    }

    /**
     * Stream every item returned by `listSessionAnnotations`, following the `cursor` cursor until
     * the server reports no further pages.
     */
    public fun listSessionAnnotationsAll(sessionId: String, limit: Long? = null, cursor: String? = null, options: RequestOptions = RequestOptions()): Flow<ListSessionAnnotationsResponseItem> = autoPaginate(
        fetch = { pageCursor -> listSessionAnnotations(sessionId = sessionId, limit = limit, cursor = pageCursor, options = options) },
        items = { it.items ?: emptyList() },
        cursor = { it.cursor },
        hasMore = { it.hasMore },
    )

    /**
     * List artifacts across all runs in session
     *
     * Lists every artifact produced by any run in this session, with the run each came from. A
     * session's runs can sit anywhere in the tenant's history and there is no per-session index,
     * so the handler pages the whole run prefix filtering by session id, bounded at 50 000 rows;
     * `truncated` is `true` when that cap bound before the prefix ran out, which is the difference
     * between "this session produced nothing" and "the scan did not reach the end". `404` when the
     * session does not exist. The entries carry names, types and sizes — fetch the bytes through
     * the files API.
     *
     * `GET /api/v1/sessions/{sessionId}/artifacts`
     *
     * Required scopes: `sessions:read`.
     */
    public suspend fun listSessionArtifacts(sessionId: String, options: RequestOptions = RequestOptions()): ListSessionArtifactsResponse {
        return client.request<ListSessionArtifactsResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/artifacts",
                options = options,
            )
        )
    }

    /**
     * List session branches
     *
     * Lists the session's alternative execution branches together with `active_branch`, the one
     * runs currently append to. The branches live inside the session record, so this is a single
     * read and there is no paging; a session may hold at most 100. `404` when the session does not
     * exist. A session that has never been branched answers with an empty list and `active_branch:
     * "main"`.
     *
     * `GET /api/v1/sessions/{sessionId}/branches`
     *
     * Required scopes: `sessions:read`.
     */
    public suspend fun listSessionBranches(sessionId: String, options: RequestOptions = RequestOptions()): ListSessionBranchesResponse {
        return client.request<ListSessionBranchesResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/branches",
                options = options,
            )
        )
    }

    /**
     * List session todos
     *
     * Lists this session's todos, up to 500, ordered by `order_index` and then by creation time.
     * `from` and `to` (ISO timestamps) narrow the list to todos whose `due_at` falls in that
     * window and reorder it by due date — note that a todo with no `due_at` is excluded entirely
     * once either bound is given, so the calendar view and the plain list do not return the same
     * set. Statuses are normalised to the canonical vocabulary before they go on the wire, so a
     * todo an agent stored as `completed` reads as `done`. `items` and `todos` carry the same
     * list. `404` when the session does not exist.
     *
     * `GET /api/v1/sessions/{sessionId}/todos`
     *
     * Required scopes: `sessions:read`.
     */
    public suspend fun listSessionTodos(sessionId: String, from: String? = null, to: String? = null, options: RequestOptions = RequestOptions()): ListSessionTodosResponse {
        val query = buildList {
            if (from != null) add("from" to from)
            if (to != null) add("to" to to)
        }
        return client.request<ListSessionTodosResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/todos",
                query = query,
                options = options,
            )
        )
    }

    /**
     * List all todos across sessions
     *
     * Lists every todo in the tenant, across all sessions, enriched with the assigned agent's
     * name. `status` and `agent_id` filter (the status filter is compared against the canonical
     * spelling, so `?status=done` also finds rows stored as `completed`), and `limit` defaults to
     * 200 with a ceiling of 500. Ordering puts the unfinished ones first by soonest due date, then
     * the finished and cancelled ones by most recently updated. `items` and `todos` carry the same
     * list; `total` counts every matching todo BEFORE `limit` is applied, so it can exceed the
     * number of entries returned. The scan over sessions is capped as a runaway backstop rather
     * than a result limit.
     *
     * `GET /api/v1/todos`
     *
     * Required scopes: `sessions:read`.
     */
    public suspend fun listTodos(options: RequestOptions = RequestOptions()): ListTodosResponse {
        return client.request<ListTodosResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/todos",
                options = options,
            )
        )
    }

    /**
     * Resolve shared session (no auth)
     *
     * Resolves a share link into the read-only view of the session behind it — the conversation
     * its owner sees: on a session with branches, the active branch's turns. No authentication —
     * the share id is the credential — so `404` covers a link that never existed, one that has
     * expired, and one that is no longer the session's current link — replaced by a later share,
     * revoked, or of a deleted session (since 2026-10-09; before, a replaced link kept serving the
     * chat even after the current one was revoked). Such a row is deleted as it is read. The body
     * carries the transcript with compacted entries dropped and any file link rewritten to the
     * share-scoped path, the plan as titles and statuses only, an execution summary for the last
     * 20 runs (tool NAMES, per-step outcome and latency, run status and duration) and the names,
     * types and sizes of the artifacts. Nothing that could reach an authenticated resource
     * travels: no run ids, no todo ids, no tool arguments or outputs, no instructions. The
     * response is sent `Cache-Control: private, no-store`.
     *
     * `GET /api/v1/shared/{shareId}`
     */
    public suspend fun resolveSharedSession(shareId: String, options: RequestOptions = RequestOptions()): ResolveSharedSessionResponse {
        return client.request<ResolveSharedSessionResponse>(
            RequestSpec(
                method = "GET",
                path = "/api/v1/shared/${encodePathSegment(shareId)}",
                options = options,
            )
        )
    }

    /**
     * Revoke session share link
     *
     * Deletes the share record and its public lookup, so the `/shared/{shareId}` URL stops
     * resolving. The session itself is untouched. Irreversible for that link — a new `POST` mints
     * a different share id. 204 whether or not a share existed.
     *
     * `DELETE /api/v1/sessions/{sessionId}/share`
     *
     * Required scopes: `runs:create`, `sessions:write`.
     */
    public suspend fun revokeSessionShare(sessionId: String, options: RequestOptions = RequestOptions()) {
        client.requestUnit(
            RequestSpec(
                method = "DELETE",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/share",
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Run a pending todo immediately
     *
     * Dispatches the todo's run now instead of waiting for its due time. Only `pending` /
     * `pending_confirmation` todos can be run; anything else answers 409. A recurring todo keeps
     * its cron (next occurrence recomputed from now); a one-shot todo's schedule entry is dropped
     * so it cannot fire twice.
     *
     * `POST /api/v1/sessions/{sessionId}/todos/{todoId}/run`
     *
     * Required scopes: `sessions:write`.
     */
    public suspend fun runSessionTodoNow(sessionId: String, todoId: String, options: RequestOptions = RequestOptions()): Todo {
        return client.request<Todo>(
            RequestSpec(
                method = "POST",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/todos/${encodePathSegment(todoId)}/run",
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Send message
     *
     * Submits a user message to the session and schedules a run on the bound agent. Returns `202
     * Accepted` with the new run id; subscribe to `/api/v1/runs/{runId}/events` (SSE) for
     * streaming output.
     *
     * `POST /api/v1/sessions/{sessionId}/messages`
     *
     * Required scopes: `runs:create`, `sessions:write`.
     */
    public suspend fun sendSessionMessage(sessionId: String, body: SendSessionMessageRequest, options: RequestOptions = RequestOptions()): SendSessionMessageResponse {
        return client.request<SendSessionMessageResponse>(
            RequestSpec(
                method = "POST",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/messages",
                body = Body.Json(uarpJson.encodeToString(body)),
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Save feedback/reaction for a session run
     *
     * `message_id` is stored as sent. The canonical form is the id `GET
     * /sessions/{sessionId}/messages` serves for the entry (`{run_id}`, `{run_id}-reply\[-N\]`,
     * `{run_id}-user-N`, `{run_id}-tool-N`, `{run_id}-system-N`); any other string is accepted —
     * older iOS builds send `{run_id}-{timestamp}-assistant-{hash}` and App Store never retires
     * them — but cannot be matched back to the transcript, and each such arrival is counted per
     * day (owner's decision 2026-09-11, option A: a 422 comes no earlier than a month of zero).
     *
     * WRITE SEMANTICS: replaces. The caller's row for this `message_id` is overwritten whole with
     * `reaction`, a fresh `created_at` and `reason` when one is sent, so an omitted or empty
     * `reason` drops a previously stored one. Other callers' rows and other messages' rows are
     * untouched.
     *
     * `PUT /api/v1/sessions/{sessionId}/runs/{runId}/feedback`
     *
     * Required scopes: `sessions:write`.
     */
    public suspend fun setSessionRunFeedback(sessionId: String, runId: String, body: SetSessionRunFeedbackRequest, options: RequestOptions = RequestOptions()): RunFeedbackSet {
        return client.request<RunFeedbackSet>(
            RequestSpec(
                method = "PUT",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/runs/${encodePathSegment(runId)}/feedback",
                body = Body.Json(uarpJson.encodeToString(body)),
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Stream session events (SSE)
     *
     * Server-Sent Events of the session: `connected`, `run_added`, every run event by type,
     * `run_done`, `session_closed`, and — for the session's drawings (docs/DESIGNER-CANVAS.md
     * §5.4) — `drawing.created` (data: Drawing) and `drawing.ops` (data: { drawing_id, from_seq,
     * to_seq, items: DrawingJournalEntry\[\] }, up to 100 entries a frame). Event ids are
     * `<runId>:<seq>` and `drawing:<drawingId>:<seq>`; send the last one as `Last-Event-ID` to
     * resume. An unknown event name is ignored by clients, which is how new ones arrive.
     *
     * `GET /api/v1/sessions/{sessionId}/events`
     *
     * Required scopes: `sessions:read`.
     *
     * Returns a cold flow of server-sent events.
     */
    public fun streamSessionEvents(sessionId: String, token: String? = null, lastEventId: String? = null, options: RequestOptions = RequestOptions()): Flow<ServerEvent> {
        val query = buildList {
            if (token != null) add("token" to token)
        }
        val headers = buildList {
            if (lastEventId != null) add("Last-Event-ID" to lastEventId)
        }
        return client.stream(
            RequestSpec(
                method = "GET",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/events",
                query = query,
                headers = headers,
                options = options,
            )
        )
    }

    /**
     * Update session metadata
     *
     * WRITE SEMANTICS: merges. Only `metadata` is writable and it merges one level into what is
     * stored, so keys the body omits survive and keys accumulate across calls; the merged result
     * is checked against the key-count, nesting-depth and byte ceilings and `422` if it would
     * exceed one. `model_override` is accepted and deliberately ignored — the runtime always uses
     * the platform default model — so old clients that still send it keep working. Malformed JSON
     * is `400` and an unknown session is `404`; the write is a read-modify-write under optimistic
     * concurrency, retried on conflict so a concurrent branch switch cannot be clobbered.
     *
     * `PUT /api/v1/sessions/{sessionId}`
     *
     * Required scopes: `sessions:write`.
     */
    public suspend fun update(sessionId: String, body: UpdateSessionRequest, options: RequestOptions = RequestOptions()): Session {
        return client.request<Session>(
            RequestSpec(
                method = "PUT",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}",
                body = Body.Json(uarpJson.encodeToString(body)),
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Update annotation (e.g. resolve)
     *
     * Updates one annotation. `resolved` is the only field applied — `content`, `author` and the
     * anchored `message_id` cannot be changed through this route, and a body naming them succeeds
     * without changing them. `404` when the session or the annotation does not exist. Returns the
     * annotation as stored.
     *
     * WRITE SEMANTICS: merges. Only `resolved` is applied, and only when the body sends it; every
     * other stored field keeps its value. The schema strips unknown keys, so a body naming
     * `content`, `author` or `message_id` succeeds and changes nothing.
     *
     * `PATCH /api/v1/sessions/{sessionId}/annotations/{annotationId}`
     *
     * Required scopes: `runs:create`, `sessions:write`.
     */
    public suspend fun updateSessionAnnotation(sessionId: String, annotationId: String, body: UpdateSessionAnnotationRequest? = null, options: RequestOptions = RequestOptions()): SessionAnnotation {
        return client.request<SessionAnnotation>(
            RequestSpec(
                method = "PATCH",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/annotations/${encodePathSegment(annotationId)}",
                body = body?.let { Body.Json(uarpJson.encodeToString(it)) },
                idempotent = true,
                options = options,
            )
        )
    }

    /**
     * Update a todo
     *
     * WRITE SEMANTICS: merges — only the fields present in the body are applied and the rest of
     * the todo is kept. `status` is normalised to the canonical spelling before storage; `due_at`,
     * `assign_agent_id`, `assign_team_id` and `recurrence` accept `null` to clear them. Any change
     * to title, instructions, status, due time, assignee or recurrence re-derives the background
     * schedule row from the resulting todo — rescheduling it, re-targeting it, or deleting it when
     * the todo becomes unscheduled, terminal, or due more than five minutes in the past. `404`
     * when the session or the todo does not exist. Returns the stored todo.
     *
     * `PATCH /api/v1/sessions/{sessionId}/todos/{todoId}`
     *
     * Required scopes: `sessions:write`.
     */
    public suspend fun updateSessionTodo(sessionId: String, todoId: String, body: UpdateSessionTodoRequest, options: RequestOptions = RequestOptions()): Todo {
        return client.request<Todo>(
            RequestSpec(
                method = "PATCH",
                path = "/api/v1/sessions/${encodePathSegment(sessionId)}/todos/${encodePathSegment(todoId)}",
                body = Body.Json(uarpJson.encodeToString(body)),
                idempotent = true,
                options = options,
            )
        )
    }
}

/**
 * Conversation sessions
 */
public val UarpClient.sessions: SessionsApi get() = SessionsApi(this)
